# -*- coding: utf-8 -*-
from pyrevit import revit, DB, forms

doc = revit.doc

def set_parameter_value(param, value):
    if not param or param.IsReadOnly:
        return False
    try:
        param.Set(value)
        return True
    except Exception:
        return False

def main():
    proj_info = getattr(doc, 'ProjectInformation', None)
    if not proj_info:
        forms.alert('Project Information element could not be found.', exitscript=True)

    current_client = ''
    client_param = proj_info.get_Parameter(DB.BuiltInParameter.CLIENT_NAME)
    if client_param and client_param.HasValue:
        current_client = client_param.AsString() or ''

    current_date = ''
    date_param = proj_info.get_Parameter(DB.BuiltInParameter.PROJECT_ISSUE_DATE)
    if date_param and date_param.HasValue:
        current_date = date_param.AsString() or ''

    client_name = forms.ask_for_string(
        prompt='Enter Client Name:',
        title='Project Info Filler',
        default=current_client
    )
    if client_name is None:
        return

    issue_date = forms.ask_for_string(
        prompt='Enter Project Issue Date:',
        title='Project Info Filler',
        default=current_date
    )
    if issue_date is None:
        return

    updated_fields = []
    with revit.Transaction('Update Project Information'):
        was_pinned = proj_info.Pinned
        if was_pinned:
            proj_info.Pinned = False

        if client_name.strip():
            if set_parameter_value(client_param, client_name.strip()):
                updated_fields.append('Client Name')

        if issue_date.strip():
            if set_parameter_value(date_param, issue_date.strip()):
                updated_fields.append('Project Issue Date')

        if was_pinned:
            proj_info.Pinned = True

    if updated_fields:
        forms.alert('Updated successfully: {}'.format(', '.join(updated_fields)), title='Success')
    else:
        forms.alert('No changes were made or parameters were read-only.', title='Info')

if __name__ == '__main__':
    main()
